'use strict';
const VERSION=1, APP_ID='year9-week3-theory';
const teacher=new URLSearchParams(location.search).get('teacher')==='1';
const STORAGE=APP_ID+(teacher?'-teacher':'-student');
let activeStorage=STORAGE;
try{if(localStorage.getItem(STORAGE+'-route')==='guided')activeStorage=STORAGE+'-guided';}catch{}
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const FIELDS=new Map();
const START_OPTIONS=[['prior',UI.prior],['supported',UI.supported],['new',UI.new],['unchecked',UI.unchecked]];
const SUPPORT_OPTIONS=[['independent',UI.independent],['prompt',UI.prompt],['help',UI.help],['unattempted',UI.unattempted]];
const PHASE_OPTIONS=[['new',UI.newLearning],['consolidating',UI.consolidating],['treading',UI.treading],['drowning',UI.drowning],['unattempted',UI.unattempted]];
const register=(id,label,options)=>FIELDS.set(id,{id,label,options});
const ALL_QUESTIONS=[...STARTER,...DATA.questions,...OPS.questions,...CHALLENGES,...PLENARY.questions];
for(const q of ALL_QUESTIONS){register(q.id,q.prompt,q.options?.map((x,i)=>[String(i),x]));register(q.id+'_support',B(q.prompt.en+' · Support',q.prompt.ms+' · Sokongan',q.prompt.zh+' · 支持程度'),SUPPORT_OPTIONS);}
for(const t of TRACES){for(const [line] of t.rows)for(const col of t.columns)register(`${t.id}_${line}_${col}`,B(`${t.title.en} · line ${line} · ${col}`,`${t.title.ms} · baris ${line} · ${col}`,`${t.title.zh} · 第${line}行 · ${col}`));register(t.id+'_explain',t.explain);register(t.id+'_support',B(t.title.en+' · Support',t.title.ms+' · Sokongan',t.title.zh+' · 支持程度'),SUPPORT_OPTIONS);}
SEQUENCE.lines.forEach((x,i)=>register('seq'+i,B('Sequence · '+x,'Urutan · '+x,'顺序 · '+x),['1','2','3'].map(x=>[x,x])));
for(const topic of TOPICS){register('start_'+topic.id,topic.title,START_OPTIONS);register('phase_'+topic.id,topic.title,PHASE_OPTIONS);}
register('start_focus',REFLECT.focus,TOPICS.map(t=>[t.id,t.title]));register('start_note',REFLECT.startNote);
register('end_focus',REFLECT.priority,TOPICS.map(t=>[t.id,t.title]));register('end_support',UI.support,SUPPORT_OPTIONS);register('end_note',REFLECT.endNote);register('name',UI.name);register('student_name',ENTRY.fullName);register('student_class',ENTRY.className);
register('d4_code',DATA_GUIDE.d4CodeLabel);
const DATA_ANNOTATION_IDS=[];
for(const line of [1,2,3])for(const part of ['name','value','type','role']){
 const id=`d5_${line}_${part}`;DATA_ANNOTATION_IDS.push(id);
 const label=DATA_GUIDE[{name:'exampleName',value:'exampleValue',type:'exampleType',role:'role'}[part]];
 register(id,B(`Question 5 · line ${line} · ${label.en}`,`Soalan 5 · baris ${line} · ${label.ms}`,`第5题 · 第${line}行 · ${label.zh}`),part==='type'?['int','float','str','bool'].map(type=>[type,type]):part==='role'?[['variable',DATA_GUIDE.variable],['constant',DATA_GUIDE.constant]]:undefined);
}
const OPERATOR_RESPONSE_IDS=['o7'];
for(const op of ['or','and'])for(const part of ['condition','output']){const id=`o7_${op}_${part}`;OPERATOR_RESPONSE_IDS.push(id);register(id,B(`Question 7 · ${op} · ${part}`,`Soalan 7 · ${op} · ${part==='condition'?'syarat':'output'}`,`第7题 · ${op} · ${part==='condition'?'条件':'输出'}`),part==='condition'?[['True','True'],['False','False']]:undefined);}
for(const t of OP_GUIDE.tasks)for(const part of ['prediction','code','output','last_code','run_status','explain']){const id=t.id+'_'+part;OPERATOR_RESPONSE_IDS.push(id);const label=part==='prediction'?OP_GUIDE.prediction:part==='code'?OP_GUIDE.codeLabel:part==='output'?UI.output:part==='explain'?OP_GUIDE.reflection:part==='last_code'?B('Code used for the last run','Kod bagi larian terakhir','上次运行的代码'):B('Run status','Status larian','运行状态');register(id,B(t.title.en+' · '+label.en,t.title.ms+' · '+label.ms,t.title.zh+' · '+label.zh),part==='run_status'?[['done',B('Finished','Selesai','完成')],['error',OP_GUIDE.error],['timeout',OP_GUIDE.timeout],['unavailable',OP_GUIDE.unavailable]]:undefined);}
const PYTHON_TASKS=[...OP_GUIDE.tasks,...CHALLENGE_LEVELS.tasks];
const CHALLENGE_RESPONSE_IDS=[];
function challengeField(id,label){CHALLENGE_RESPONSE_IDS.push(id);register(id,label);}
for(const [term,name] of CHALLENGE_LEVELS.terms)for(const part of ['meaning','example']){const label=part==='meaning'?CHALLENGE_LEVELS.ownWords:CHALLENGE_LEVELS.codeEvidence;challengeField(`c1_${term}_${part}`,B(`${name.en} · ${label.en}`,`${name.ms} · ${label.ms}`,`${name.zh} · ${label.zh}`));}
for(const [id] of CHALLENGE_LEVELS.compareCases)for(const part of ['or','and','actual']){const label=part==='or'?CHALLENGE_LEVELS.orPrediction:part==='and'?CHALLENGE_LEVELS.andPrediction:CHALLENGE_LEVELS.actual;challengeField(`c2_${id}_${part}`,B(`Level 2 · case ${id.toUpperCase()} · ${label.en}`,`Tahap 2 · kes ${id.toUpperCase()} · ${label.ms}`,`第2级 · 案例${id.toUpperCase()} · ${label.zh}`));}
for(const [id,value] of CHALLENGE_LEVELS.testCases)for(const part of ['prediction','actual']){const label=part==='prediction'?CHALLENGE_LEVELS.prediction:CHALLENGE_LEVELS.actual;challengeField(`c3_${id}_${part}`,B(`Level 3 · ${value} · ${label.en}`,`Tahap 3 · ${value} · ${label.ms}`,`第3级 · ${value} · ${label.zh}`));}
for(const t of CHALLENGE_LEVELS.tasks)for(const part of ['code','output','last_code','run_status']){const label=part==='code'?OP_GUIDE.codeLabel:part==='output'?UI.output:part==='last_code'?B('Code used for the last run','Kod bagi larian terakhir','上次运行的代码'):B('Run status','Status larian','运行状态');challengeField(t.id+'_'+part,B(t.title.en+' · '+label.en,t.title.ms+' · '+label.ms,t.title.zh+' · '+label.zh));}
register('c2',CHALLENGE_LEVELS.compareSteps[3]);register('c3',CHALLENGE_LEVELS.finalExplain);
const EXIT_RESPONSE_IDS=['exit_learned'];
register('exit_learned',EXIT_CHECKS.learned);
for(const [key,situation] of EXIT_CHECKS.rows)for(const part of ['type','assignment','reason']){const id=`exit_${key}_${part}`;EXIT_RESPONSE_IDS.push(id);const label=EXIT_CHECKS[part];register(id,B(`${situation.en} · ${label.en}`,`${situation.ms} · ${label.ms}`,`${situation.zh} · ${label.zh}`));}
for(const [id,label] of [['exit_boolean',EXIT_CHECKS.boolean],['exit_constants_code',EXIT_CHECKS.constantsCode],['exit_constants_explain',EXIT_CHECKS.constantsExplain]]){EXIT_RESPONSE_IDS.push(id);register(id,label);}
SUPPORTED.registerFields();
function fresh(){return {app:APP_ID,version:VERSION,page:0,lang:'en',mode:'focus',answers:{},checked:{},models:{},walks:{},first:{},updated:null};}
function validate(raw){if(!raw||raw.app!==APP_ID||raw.version!==VERSION)throw Error('Wrong lesson or version');let s=fresh();s.page=Number.isInteger(raw.page)&&raw.page>=0&&raw.page<PAGES.length?raw.page:0;s.lang=['en','ms','zh'].includes(raw.lang)?raw.lang:'en';s.mode=raw.mode==='compare'?'compare':'focus';
 for(const [id,f]of FIELDS){const v=raw.answers?.[id];if(typeof v==='string'&&v.length<=30000&&(!f.options||v===''||f.options.some(o=>o[0]===v)))s.answers[id]=v;}
 for(const q of ALL_QUESTIONS){if(raw.checked?.[q.id]===true)s.checked[q.id]=true;if(raw.models?.[q.id]===true)s.models[q.id]=true;}
 for(const id of FIELDS.keys()){if(raw.models?.[id]===true)s.models[id]=true;if(id.startsWith('g_')&&raw.checked?.[id]===true)s.checked[id]=true;}
 for(const t of TRACES)if(raw.checked?.['g_trace_'+t.id]===true)s.checked['g_trace_'+t.id]=true;
 for(const t of TRACES){if(raw.checked?.[t.id]===true)s.checked[t.id]=true;const w=raw.walks?.[t.id];if(Number.isInteger(w)&&w>=0&&w<=t.steps.length)s.walks[t.id]=w;}
 if(raw.checked?.sequence===true)s.checked.sequence=true;
 if(raw.first&&typeof raw.first==='object')for(const [id,entry]of Object.entries(raw.first)){if((FIELDS.has(id)||TRACES.some(t=>t.id===id))&&entry&&typeof entry==='object'){const values={};for(const [key,v]of Object.entries(entry.values||{}))if(FIELDS.has(key)&&typeof v==='string'&&v.length<=30000)values[key]=v;s.first[id]={at:typeof entry.at==='string'?entry.at.slice(0,40):'',values};}}
 s.updated=typeof raw.updated==='string'?raw.updated.slice(0,40):null;return s;}
let state=fresh(),storageOK=true;
try{const raw=localStorage.getItem(activeStorage);if(raw)state=validate(JSON.parse(raw));}catch{storageOK=false;}
let updateStep=0;
let entryVisible=!teacher,entryError=false;
let entryDraft={name:state.answers.student_name||state.answers.name||'',className:state.answers.student_class||''};
function text(b){return typeof b==='string'?b:(b?.[state.lang]??b?.en??'');}
function bi(b){if(typeof b==='string')return e(b);if(state.mode==='compare'&&state.lang!=='en')return `<span class="compare"><span lang="en">${e(b.en)}</span><span class="secondary-lang" lang="${state.lang==='zh'?'zh-Hans':state.lang}">${e(text(b))}</span></span>`;return e(text(b));}
const val=id=>state.answers[id]??'';
function toast(b){document.querySelector('#notice').textContent=text(b);clearTimeout(toast.timer);toast.timer=setTimeout(()=>document.querySelector('#notice').textContent='',6500);}
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(activeStorage,JSON.stringify(state));localStorage.setItem(STORAGE+'-route',activeStorage===STORAGE?'standard':'guided');storageOK=true;}catch{storageOK=false;}const status=document.querySelector('#saveStatus');if(status)status.textContent=text(storageOK?UI.saved:UI.saveError);}
function remember(id,ids=[id]){if(!state.first[id])state.first[id]={at:new Date().toISOString(),values:Object.fromEntries(ids.map(key=>[key,val(key)]))};}
function setAnswer(id,value){if(!FIELDS.has(id)||typeof value!=='string'||value.length>30000)throw Error('Invalid answer');const f=FIELDS.get(id);if(f.options&&value!==''&&!f.options.some(o=>o[0]===value))throw Error('Invalid choice');state.answers[id]=value;delete state.checked[id];if(id.startsWith('g_t')){const t=TRACES.find(t=>id.startsWith('g_'+t.id+'_'));if(t)delete state.checked['g_trace_'+t.id];}if(id.startsWith('seq'))delete state.checked.sequence;for(const t of TRACES)if(t.rows.some(([line])=>t.columns.some(col=>id===`${t.id}_${line}_${col}`)))delete state.checked[t.id];save();}
function select(id,label=FIELDS.get(id).label,options=FIELDS.get(id).options){return `<label class="field" for="${id}"><span>${bi(label)}</span><select id="${id}" data-field="${id}"><option value="">${e(text(UI.choose))}</option>${options.map(([v,label])=>`<option value="${e(v)}" ${val(id)===v?'selected':''}>${e(text(label))}</option>`).join('')}</select></label>`;}
function writing(id,label=FIELDS.get(id).label){return `<label class="field" for="${id}"><span>${bi(label)}</span><textarea id="${id}" data-field="${id}" maxlength="30000" rows="4">${e(val(id))}</textarea></label>`;}
function question(q,i){return `<section class="question" id="question-${q.id}"><div class="qnumber">${String(i+1).padStart(2,'0')}</div>${q.options?`<fieldset style="border:0;padding:0;margin:0"><legend>${bi(q.prompt)}</legend><div class="options">${q.options.map((label,n)=>`<label class="option"><input type="radio" name="${q.id}" id="${q.id}-${n}" data-field="${q.id}" value="${n}" ${val(q.id)===String(n)?'checked':''}><span>${bi(label)}</span></label>`).join('')}</div></fieldset><button data-check="${q.id}">${bi(UI.check)}</button>${state.checked[q.id]?`<div class="feedback ${val(q.id)===String(q.answer)?'correct':''}" role="status"><strong>${bi(val(q.id)===String(q.answer)?UI.correct:UI.rethink)}</strong><p>${bi(q.why)}</p></div>`:''}`:`${writing(q.id)}<p class="hint">${bi(UI.note)}</p><details data-model="${q.id}" ${state.models[q.id]?'open':''}><summary>${bi(UI.model)}</summary><p>${bi(q.example)}</p></details>`}</section>`;}
function pageHead(id,title,intro){return `<p class="eyebrow">${bi(UI[id])}</p><h1>${bi(title||UI[id])}</h1>${intro?`<div class="lede">${bi(intro)}</div>`:''}`;}
function updateCode(){const step=UPDATE_TUTOR.steps[updateStep];return ['warning_count = 1','warning_count = warning_count + 1'].map((line,i)=>{
 const active=step.line===i+1;
 let code=e(line);
 if(active&&i===1){const destination=step.focus==='store'?'<mark>warning_count</mark>':'warning_count';const right=step.focus==='read'?'<mark>warning_count</mark> + 1':step.focus==='calculate'?'<mark>warning_count + 1</mark>':'warning_count + 1';code=destination+' = '+right;}
 return `<li class="${active?'active':''}" ${active?'aria-current="step"':''}><code>${code}</code></li>`;
 }).join('');}
function updateExplanation(){const step=UPDATE_TUTOR.steps[updateStep];return `<p class="tutor-position">${bi(B(`Tutor step ${updateStep+1} of 4`,`Langkah tutor ${updateStep+1} daripada 4`,`指导步骤 ${updateStep+1}/4`))}</p><h3>${bi(step.title)}</h3><p>${bi(step.note)}</p><div class="tutor-calculation"><code>${e(step.calculation)}</code></div>`;}
function updateTutor(){const step=UPDATE_TUTOR.steps[updateStep];return `<section class="panel update-tutor" aria-labelledby="updateTitle"><h2 id="updateTitle">${bi(READING.update)}</h2><p>${bi(UPDATE_TUTOR.intro)}</p><div class="grid"><div><ol class="tracecode tutor-code" id="updateCode">${updateCode()}</ol><div class="memory"><div class="slot"><span>${bi(UPDATE_TUTOR.stored)}</span><br><code>warning_count</code><strong id="memoryValue">${e(step.value)}</strong><span>int</span></div></div></div><div><div class="tutor-explanation" id="updateExplanation" role="status" aria-live="polite" aria-atomic="true">${updateExplanation()}</div><div class="actions"><button id="updateBack" data-update-back ${updateStep===0?'disabled':''}>${bi(UPDATE_TUTOR.back)}</button><button id="updateNext" class="primary" data-memory>${bi(step.next||UPDATE_TUTOR.replay)}</button></div></div></div></section>`;}
function changeUpdateStep(next){updateStep=Math.max(0,Math.min(3,next));const step=UPDATE_TUTOR.steps[updateStep];document.querySelector('#updateCode').innerHTML=updateCode();document.querySelector('#memoryValue').textContent=step.value;document.querySelector('#updateExplanation').innerHTML=updateExplanation();document.querySelector('#updateBack').disabled=updateStep===0;document.querySelector('#updateNext').innerHTML=bi(step.next||UPDATE_TUTOR.replay);}
function reading(){return pageHead('readFirst',READING.title,READING.intro)+`<div class="band"><strong>WAGBA</strong><div>${bi(LESSON.wagba)}</div></div>${updateTutor()}<section class="panel"><h2>${bi(B('What will stay fixed?','Apakah yang akan kekal?','什么保持固定？'))}</h2><p>${bi(READING.constant)}</p><pre class="code">MAX_REMINDERS = 3
warning_count = 0</pre></section><section class="panel"><h2>${bi(B('Same digits, different data','Digit sama, data berbeza','相同数字，不同数据'))}</h2><div class="grid">${READING.types.map(([type,value,desc])=>`<div><div class="memory"><div class="slot"><code>${e(type)}</code><strong>${e(value)}</strong></div></div><p>${bi(desc)}</p></div>`).join('')}</div><div class="band">${bi(READING.input)}</div></section><div class="band">${bi(READING.safety)}</div><section class="panel"><h2>${bi(B('What you are getting better at','Perkara yang anda tingkatkan','今天要提高什么'))}</h2>${LESSON.goals.map(g=>`<p>${bi(g)}</p>`).join('')}</section>`;}
function starter(){return pageHead('starter',null,B('Try all six checks. Use the reading when needed, then use the feedback to review and improve your answers.','Cuba keenam-enam semakan. Gunakan bacaan jika perlu, kemudian gunakan maklum balas untuk menyemak dan menambah baik jawapan.','尝试六项检查。需要时参考阅读材料，再根据反馈检查并改进答案。'))+`<div class="panel">${STARTER.map(question).join('')}</div>`;}
function codeLines(lines){return `<ol class="tracecode lesson-code">${lines.map(line=>`<li><code>${e(line)}</code></li>`).join('')}</ol>`;}
function dataTeaching(){const g=DATA_GUIDE;return `<div class="data-teaching">
<section class="panel guide-section"><p class="eyebrow">${bi(g.example)}</p><h2>${bi(g.anatomyTitle)}</h2><p>${bi(g.anatomyIntro)}</p><pre class="code assignment-example">messages_read = 4</pre><div class="assignment-parts">${g.parts.map(part=>`<div class="assignment-part"><code>${e(part.code)}</code><h3>${bi(part.label)}</h3><p>${bi(part.explain)}</p></div>`).join('')}</div></section>
<section class="panel guide-section"><h2>${bi(g.namesTitle)}</h2><p>${bi(g.namesIntro)}</p><div class="guide-name-grid">${g.names.map(item=>`<article class="name-example ${item.kind}"><h3>${bi(item.label)}</h3><pre class="code">${e(item.code)}</pre><p>${bi(item.why)}</p></article>`).join('')}</div><div class="band">${bi(g.namingRules)}</div></section>
<section class="panel guide-section"><h2>${bi(g.constantTitle)}</h2><p>${bi(g.constantIntro)}</p>${codeLines(g.constantCode)}<div class="line-explanations">${g.constantNotes.map((note,i)=>`<div><span class="line-badge">${i+1}</span><p>${bi(note)}</p></div>`).join('')}</div></section>
<section class="panel guide-section"><h2>${bi(g.typesTitle)}</h2><p>${bi(g.typesIntro)}</p><div class="type-examples">${g.types.map(([code,value,type,why])=>`<article class="type-example"><pre class="code">${e(code)}</pre><div class="type-value"><span><strong>${bi(g.exampleValue)}</strong> <code>${e(value)}</code></span><span><strong>${bi(g.exampleType)}</strong> <code>${e(type)}</code></span></div><p>${bi(why)}</p></article>`).join('')}</div></section>
</div>`;}
function dataPractice(){const g=DATA_GUIDE;return `<section class="panel data-practice"><h2>${bi(g.practice)}</h2><p>${bi(g.answerHint)}</p>${DATA.questions.slice(0,3).map(question).join('')}</section>
<section class="panel data-practice" id="question-d4"><h2>${bi(g.d4Title)}</h2><p>${bi(g.d4Prompt)}</p><div class="faulty-assignment"><strong>${bi(B('The beginner’s invalid assignment','Penugasan tidak sah oleh pemula','初学者的无效赋值'))}</strong><pre class="code">2 links = 3</pre></div><ol class="task-steps">${g.d4Steps.map(step=>`<li>${bi(step)}</li>`).join('')}</ol><label class="field" for="d4_code"><span>${bi(g.d4CodeLabel)}</span><textarea class="code-answer" id="d4_code" data-field="d4_code" rows="2" spellcheck="false" maxlength="30000">${e(val('d4_code'))}</textarea></label>${writing('d4',g.d4AnswerLabel)}</section>
<section class="panel data-practice" id="question-d5"><h2>${bi(g.d5Title)}</h2><p>${bi(g.d5Prompt)}</p>${codeLines(g.d5Code)}<ol class="task-steps">${g.d5Steps.map(step=>`<li>${bi(step)}</li>`).join('')}</ol><div class="tablewrap"><table class="annotation-table"><caption>${bi(B('Annotate the three starting assignments','Anotasikan tiga penugasan awal','标注三条初始赋值'))}</caption><thead><tr><th scope="col">${bi(UI.line)}</th><th scope="col">${bi(g.exampleName)}</th><th scope="col">${bi(g.exampleValue)}</th><th scope="col">${bi(g.exampleType)}</th><th scope="col">${bi(g.role)}</th></tr></thead><tbody>${[1,2,3].map(line=>`<tr><th scope="row">${line}</th>${['name','value','type','role'].map(part=>{const id=`d5_${line}_${part}`,field=FIELDS.get(id);return `<td>${field.options?`<select id="${id}" data-field="${id}" aria-label="${e(text(field.label))}"><option value="">${e(text(UI.choose))}</option>${field.options.map(([v,label])=>`<option value="${e(v)}" ${val(id)===v?'selected':''}>${e(text(label))}</option>`).join('')}</select>`:`<input class="code-answer" id="${id}" data-field="${id}" aria-label="${e(text(field.label))}" value="${e(val(id))}" maxlength="300" spellcheck="false" autocomplete="off">`}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${writing('d5',g.d5AnswerLabel)}<p class="hint">${bi(UI.note)}</p></section>`;}
function dataPage(){return pageHead('data',B('Name it clearly. Choose its purpose.','Namakan dengan jelas. Pilih tujuannya.','清晰命名，明确用途。'),DATA_GUIDE.intro)+dataTeaching()+dataPractice();}

function lessonTable(headers,rows,caption){return `<div class="tablewrap operator-table"><table><caption>${bi(caption)}</caption><thead><tr>${headers.map(h=>`<th scope="col">${bi(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>i===0?`<th scope="row">${cell}</th>`:`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
const codeCell=x=>`<code>${e(x)}</code>`;
function operatorTeaching(){const g=OP_GUIDE;return `<section class="panel guide-section"><h2>${bi(g.arithmeticTitle)}</h2><p>${bi(g.arithmeticIntro)}</p>${lessonTable([g.symbol,g.meaning,g.example,g.result,g.why],g.arithmetic.map(([op,name,example,result,why])=>[codeCell(op),bi(name),codeCell(example),codeCell(result),bi(why)]),g.arithmeticTitle)}
<h3>${bi(g.divisionTitle)}</h3><p>${bi(g.divisionIntro)}</p><div class="division-equation" role="img" aria-label="${e(text(B('11 divided by 4 equals 2.75','11 dibahagi 4 sama dengan 2.75','11 除以 4 等于 2.75')))}"><span class="fraction"><span>11</span><span>4</span></span><span>=</span><span>11 ÷ 4</span><span>=</span><strong>2.75</strong></div><div class="division-cards"><article class="math-card"><h3>${bi(g.wholeTitle)}</h3><pre class="long-division" aria-label="${e(text(B('11 divided by 4 gives a quotient of 2 and a remainder of 3','11 dibahagi 4 memberi hasil bahagi 2 dan baki 3','11 除以 4，商 2 余 3')))}">       2
     ┌────
  4  │11
     − 8
      ──
       3</pre><ol>${g.wholeSteps.map(s=>`<li>${bi(s)}</li>`).join('')}</ol></article><article class="math-card"><h3>${bi(g.decimalTitle)}</h3><pre class="long-division" aria-label="${e(text(B('Long division: 11.00 divided by 4 equals 2.75','Bahagi panjang: 11.00 dibahagi 4 sama dengan 2.75','竖式除法：11.00 除以 4 等于 2.75')))}">       2.75
     ┌─────
  4  │11.00
     − 8
      ──
       30
      −28
       ──
        20
       −20
        ──
         0</pre><ol>${g.decimalSteps.map(s=>`<li>${bi(s)}</li>`).join('')}</ol></article></div>${lessonTable([g.example,g.result,g.meaning],g.divisionRows.map(([ex,res,why])=>[codeCell(ex),codeCell(res),bi(why)]),g.divisionTitle)}
<h3>${bi(g.orderTitle)}</h3>${lessonTable([g.example,B('First simplify','Ringkaskan dahulu','先化简'),g.result,g.why],g.orderRows.map(([ex,step,res,why])=>[codeCell(ex),codeCell(step),codeCell(res),bi(why)]),g.orderTitle)}</section>
<section class="panel guide-section"><h2>${bi(g.comparisonTitle)}</h2><p>${bi(g.comparisonIntro)}</p>${lessonTable([g.example,g.meaning],g.assignmentRows.map(([ex,meaning])=>[codeCell(ex),bi(meaning)]),B('Assignment and comparison have different jobs','Penugasan dan perbandingan mempunyai tugas berbeza','赋值与比较的作用不同'))}${lessonTable([g.symbol,g.meaning,g.trueExample,g.falseExample],g.comparisons.map(([op,meaning,yes,no])=>[codeCell(op),bi(meaning),codeCell(yes+' → True'),codeCell(no+' → False')]),g.comparisonTitle)}<h3>${bi(B('Use a comparison in a program','Gunakan perbandingan dalam atur cara','在程序中使用比较'))}</h3>${codeLines(g.comparisonCode)}<div class="band">${bi(g.comparisonNote)}</div></section>
<section class="panel guide-section"><h2>${bi(g.booleanTitle)}</h2><p>${bi(g.booleanIntro)}</p>${lessonTable([g.symbol,g.meaning,g.example,g.result],g.booleans.map(([op,meaning,example,result])=>[codeCell(op),bi(meaning),codeCell(example),codeCell(result)]),g.booleanTitle)}<h3>${bi(g.truthTitle)}</h3><p>${bi(g.truthNote)}</p><div class="truth-tables">${lessonTable(['A','B','A and B','A or B'],g.truthRows.map(row=>row.map(codeCell)),B('and / or · two inputs','and / or · dua input','and / or · 两个输入'))}${lessonTable(['A','not A'],g.notRows.map(row=>row.map(codeCell)),B('not · one input','not · satu input','not · 一个输入'))}</div><h3>${bi(B('Use not to choose a branch','Gunakan not untuk memilih cabang','用 not 选择分支'))}</h3>${codeLines(g.notCode)}<div class="band">${bi(g.notNote)}</div></section>
<section class="panel guide-section"><h2>${bi(g.compareTitle)}</h2><p>${bi(g.compareIntro)}</p><div class="band">${bi(B('Read Python from top to bottom. The colon after if or else starts a branch. Indent each print line by four spaces. If the condition is True, run the if branch; otherwise run else. Only one branch runs. The print statements display the quoted text without its quotes.','Baca Python dari atas ke bawah. Titik bertindih selepas if atau else memulakan cabang. Inden setiap baris print sebanyak empat ruang. Jika syarat True, jalankan cabang if; jika tidak, jalankan else. Hanya satu cabang dijalankan. Pernyataan print memaparkan teks tanpa tanda petiknya.','从上到下阅读 Python。if 或 else 后的冒号开始一个分支。每条 print 语句缩进四个空格。条件为 True 执行 if 分支，否则执行 else，只运行一个分支。print 显示引号内的文字，不显示引号本身。'))}</div>${operatorPair(g.workedOr,g.workedAnd)}${lessonTable([g.symbol,UI.condition,g.result,g.branch,UI.output],g.workedRows.map(row=>row.map(codeCell)),B('Follow each program with the same inputs','Ikuti setiap atur cara dengan input sama','用相同输入跟踪两个程序'))}<div class="band">${bi(g.workedNote)}</div></section>`;}
function operatorPair(orCode,andCode){return `<div class="operator-pair"><article><h3>${bi(B('Rule A · or','Peraturan A · or','规则 A · or'))}</h3>${codeLines(orCode)}</article><article><h3>${bi(B('Rule B · and','Peraturan B · and','规则 B · and'))}</h3>${codeLines(andCode)}</article></div>`;}
function operatorMCQ(q,i){const examples={o1:['print(2 + 3 * 2)'],o2:[],o3:['warning_count = 2','print(warning_count >= 2)'],o4:['is_urgent = True','asks_password = False','print(is_urgent and asks_password)'],o5:['is_urgent = True','asks_password = False','print(is_urgent or asks_password)'],o6:['verified = False','print(not verified)']};const prompts={o1:B('What does this program print?','Apakah yang dicetak oleh atur cara ini?','这个程序输出什么？'),o3:B('Predict the comparison result.','Ramal hasil perbandingan.','预测比较结果。'),o4:B('Predict the result of and.','Ramal hasil and.','预测 and 的结果。'),o5:B('For the same values, predict the result of or.','Bagi nilai sama, ramal hasil or.','使用相同的值，预测 or 的结果。'),o6:B('Predict the result of not.','Ramal hasil not.','预测 not 的结果。')};let rendered=question({...q,prompt:prompts[q.id]||q.prompt},i);return examples[q.id]?.length?rendered.replace('<div class="options">',`${codeLines(examples[q.id])}<div class="options">`):rendered;}
function operatorComparisonTask(){const g=OP_GUIDE;return `<section class="panel data-practice" id="question-o7"><h2>${bi(g.q7Title)}</h2><p>${bi(g.q7Prompt)}</p>${operatorPair(g.q7Or,g.q7And)}<div class="tablewrap"><table><caption>${bi(UI.predictions)}</caption><thead><tr><th>${bi(g.symbol)}</th><th>${bi(UI.condition)}</th><th>${bi(UI.output)}</th></tr></thead><tbody>${['or','and'].map(op=>`<tr><th scope="row"><code>${op}</code></th><td>${select(`o7_${op}_condition`,UI.condition,[['True','True'],['False','False']])}</td><td><label class="field" for="o7_${op}_output"><span>${bi(UI.output)} · ${op}</span><input id="o7_${op}_output" data-field="o7_${op}_output" value="${e(val(`o7_${op}_output`))}" maxlength="100" autocomplete="off"></label></td></tr>`).join('')}</tbody></table></div>${writing('o7',g.q7Answer)}</section>`;}
function programCode(id){return Object.prototype.hasOwnProperty.call(state.answers,id+'_code')?val(id+'_code'):PYTHON_TASKS.find(t=>t.id===id).starter.join('\n')+'\n';}
let pythonBusy=null,pythonWorker=null,pythonTimer=null;
function pythonOutput(id){if(pythonBusy===id)return `<p>${bi(OP_GUIDE.running)}</p>`;const status=val(id+'_run_status');if(!status)return `<p class="hint">${bi(OP_GUIDE.emptyRun)}</p>`;const changed=programCode(id)!==val(id+'_last_code');return `${changed?`<p class="band">${bi(OP_GUIDE.changed)}</p>`:''}${status==='error'?`<p>${bi(OP_GUIDE.error)}</p>`:status==='timeout'?`<p>${bi(OP_GUIDE.timeout)}</p>`:status==='unavailable'?`<p>${bi(OP_GUIDE.unavailable)}</p>`:''}${val(id+'_output')?`<pre class="code python-result">${e(val(id+'_output'))}</pre>`:status==='done'?`<p>${bi(OP_GUIDE.noOutput)}</p>`:''}`;}
function refreshPythonOutputs(){for(const t of PYTHON_TASKS){const box=document.querySelector('#'+t.id+'_run_result');if(box)box.innerHTML=pythonOutput(t.id);const button=document.querySelector('#'+t.id+'_run_button');if(button)button.disabled=Boolean(pythonBusy);}}
function runPythonTask(id){if(pythonBusy||!PYTHON_TASKS.some(t=>t.id===id))return;const code=programCode(id);setAnswer(id+'_code',code);remember(id+'_code',[id+'_code',...(id.startsWith('c')?CHALLENGE_RESPONSE_IDS.filter(key=>key.startsWith(id+'_')&&!['code','output','last_code','run_status'].some(part=>key===id+'_'+part)):id.startsWith('g_')?SUPPORTED.predictionFields(id):[id+'_prediction'])]);pythonBusy=id;let output='',finished=false;refreshPythonOutputs();const finish=(status,extra='')=>{if(finished)return;finished=true;clearTimeout(pythonTimer);pythonWorker?.terminate();pythonWorker=null;pythonBusy=null;state.answers[id+'_last_code']=code;state.answers[id+'_output']=(output+extra).slice(0,6000);state.answers[id+'_run_status']=status;save();refreshPythonOutputs();};try{pythonWorker=new Worker('operator-worker.js?v=20260913-1');pythonWorker.onmessage=({data})=>{if(data.type==='output')output=(output+String(data.text)).slice(0,6000);else if(data.type==='done')finish('done');else if(data.type==='error')finish('error','\n'+String(data.error));};pythonWorker.onerror=()=>finish('unavailable');pythonTimer=setTimeout(()=>finish('timeout'),4500);pythonWorker.postMessage({type:'run',code});}catch{finish('unavailable');}}
function pythonEditor(t){return `<label class="field" for="${t.id}_code"><span>${bi(OP_GUIDE.codeLabel)}</span><textarea class="code-answer python-editor" id="${t.id}_code" data-field="${t.id}_code" rows="9" spellcheck="false" autocapitalize="off" autocomplete="off" maxlength="20000">${e(programCode(t.id))}</textarea></label><button class="primary" id="${t.id}_run_button" data-python-run="${t.id}" ${pythonBusy?'disabled':''}>${bi(OP_GUIDE.run)}</button><div class="python-output" id="${t.id}_run_result" role="status" aria-live="polite">${pythonOutput(t.id)}</div>`;}
function programmingTask(t){return `<section class="panel data-practice" id="question-${t.id}"><h2>${bi(t.title)}</h2><p>${bi(t.prompt)}</p>${writing(t.id+'_prediction',OP_GUIDE.prediction)}${pythonEditor(t)}<div class="band">${bi(t.follow)}</div>${writing(t.id+'_explain',OP_GUIDE.reflection)}</section>`;}
function operatorsPage(){return pageHead('operators',B('Calculate. Compare. Choose a branch.','Kira. Banding. Pilih cabang.','计算、比较、选择分支。'),OP_GUIDE.intro)+operatorTeaching()+`<section class="panel data-practice"><h2>${bi(OP_GUIDE.practice)}</h2>${OPS.questions.slice(0,6).map(operatorMCQ).join('')}</section>`+operatorComparisonTask()+OP_GUIDE.tasks.map(programmingTask).join('');}

const normalAnswer=x=>String(x).trim().toLowerCase().replace(/^["']|["']$/g,'').replace(/^[-–—]$/,'—');
function traceResult(t){let correct=0,total=0,attempted=0;for(const [line,expected]of t.rows)t.columns.forEach((col,i)=>{const v=val(`${t.id}_${line}_${col}`);total++;if(v.trim())attempted++;if(v.trim()&&normalAnswer(v)===normalAnswer(expected[i]))correct++;});return{correct,total,attempted};}
function tracePanel(t){const n=state.walks[t.id]||0,current=t.steps[n-1];const checked=state.checked[t.id];const result=traceResult(t);return `<section class="panel"><h2>${bi(t.title)}</h2><p>${bi(t.context)}</p><div class="grid"><div><ol class="tracecode">${t.code.map((line,i)=>`<li class="${current?.line===i+1?'active':''}">${e(line)}</li>`).join('')}</ol><div class="actions"><button data-walk="${t.id}" class="primary" ${n>=t.steps.length?'disabled':''}>${bi(UI.readLine)}</button><button data-restart="${t.id}">${bi(UI.restart)}</button></div><div aria-live="polite">${current?`<div class="memory">${Object.entries(current.values).map(([key,value])=>`<div class="slot"><code>${e(key)}</code><strong>${e(value)}</strong></div>`).join('')}</div><p class="band">${bi(current.note)}</p><p><strong>${bi(UI.output)}:</strong> ${current.output?`<code>${e(current.output)}</code>`:bi(UI.noOutput)}</p>`:`<p class="hint">${bi(B('Predict in the table first. Then step through to compare. Opening the walkthrough is recorded as support viewed; it does not decide your learning phase.','Ramal dalam jadual dahulu. Kemudian jejak untuk membandingkan. Membuka panduan direkodkan sebagai sokongan dilihat; ia tidak menentukan fasa pembelajaran.','先在表中预测，再逐行比较。打开演示会记录为查看过支持，不会自动决定学习阶段。'))}</p>`}</div></div><div><h3>${bi(UI.predictions)}</h3><p class="hint">${bi(B('Record values after the stated line. “Condition result” records the if decision on that line only. Output means new text printed on that line. Use — when neither happens.','Catat nilai selepas baris dinyatakan. “Hasil syarat” merekod keputusan if pada baris itu sahaja. Output ialah teks baharu dicetak pada baris itu. Gunakan — jika tiada.','填写指定行执行后的值。“条件结果”只记录该行的 if 判断；“输出”指该行新显示的文本。没有发生时写 —。'))}</p><div class="tablewrap"><table><thead><tr><th scope="col">${bi(UI.line)}</th>${t.columns.map(c=>`<th scope="col">${UI[c]?bi(UI[c]):e(c)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(([line,answers])=>`<tr><th scope="row">${line}</th>${t.columns.map((col,j)=>{const id=`${t.id}_${line}_${col}`;return `<td><input id="${id}" data-field="${id}" aria-label="${e(text(FIELDS.get(id).label))}" value="${e(val(id))}" maxlength="60" autocomplete="off">${checked?`<div class="hint">${val(id).trim()?(normalAnswer(val(id))===normalAnswer(answers[j])?'✓':`→ ${e(answers[j])}`):`${e(text(UI.unattempted))} · ${e(answers[j])}`}</div>`:''}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><button data-trace-check="${t.id}">${bi(UI.check)}</button>${checked?`<div class="feedback" role="status">${bi(B(`${result.correct} of ${result.attempted} attempted cells match; ${result.total-result.attempted} not attempted. Compare the walkthrough to understand each update.`,`${result.correct} daripada ${result.attempted} sel dicuba sepadan; ${result.total-result.attempted} belum dicuba. Bandingkan panduan untuk memahami setiap kemas kini.`,`${result.attempted} 个已尝试单元格中有 ${result.correct} 个匹配；${result.total-result.attempted} 个尚未尝试。参考逐行演示理解每次更新。`))}</div>`:''}</div></div>${writing(t.id+'_explain')}<details data-model="${t.id}_explain"><summary>${bi(UI.model)}</summary><p>${bi(TRACE_MODELS[TRACES.indexOf(t)])}</p></details></section>`;}
const workedTraceSteps={setup:0,decision:0};
function workedTraceCode(example){const index=workedTraceSteps[example.id],current=example.rows[index].line;return example.code.map((line,i)=>`<li class="${current===i+1?'active':''} ${example.id==='decision'&&index===3&&i>=4?'skipped-code':''}" ${current===i+1?'aria-current="step"':''}><code>${e(line)}</code></li>`).join('');}
function workedTraceRows(example){const current=workedTraceSteps[example.id];return example.rows.map((row,i)=>`<tr class="${i===current?'current-trace-row':''}" ${i===current?'aria-current="step"':''}><th scope="row">${row.line}</th>${row.values.map((value,col)=>`<td class="${i===current&&row.changed.includes(col)?'changed-trace-cell':''}">${i===current&&row.changed.includes(col)?`<strong>${e(value)}</strong>`:`<code>${e(value)}</code>`}</td>`).join('')}</tr>`).join('');}
function workedTraceExplanation(example){const index=workedTraceSteps[example.id];return `<p class="tutor-position">${bi(B(`Tutor step ${index+1} of ${example.rows.length} · line ${example.rows[index].line}`,`Langkah tutor ${index+1} daripada ${example.rows.length} · baris ${example.rows[index].line}`,`指导步骤 ${index+1}/${example.rows.length} · 第${example.rows[index].line}行`))}</p><p>${bi(example.notes[index])}</p>`;}
function workedTraceOutput(example){const outputColumn=example.columns.indexOf('output');const lines=example.rows.slice(0,workedTraceSteps[example.id]+1).map(row=>row.values[outputColumn]).filter(value=>value!=='—');return lines.length?`<pre class="code">${e(lines.join('\n'))}</pre>`:`<p class="hint">${bi(UI.noOutput)}</p>`;}
function workedTraceExample(example){const g=TRACE_TEACHING,id=example.id,index=workedTraceSteps[id];return `<section class="panel guide-section worked-trace" aria-labelledby="worked-${id}-title"><h2 id="worked-${id}-title">${bi(example.title)}</h2><p>${bi(example.context)}</p><div class="grid"><div><ol class="tracecode tutor-code" id="worked-${id}-code">${workedTraceCode(example)}</ol><h3 class="trace-output-title">${bi(g.outputTitle)}</h3><div id="worked-${id}-output">${workedTraceOutput(example)}</div></div><div><div id="worked-${id}-explanation" class="tutor-explanation" role="status" aria-live="polite" aria-atomic="true">${workedTraceExplanation(example)}</div><div class="actions"><button id="worked-${id}-back" data-worked-trace="${id}" data-direction="back" ${index===0?'disabled':''}>${bi(g.previous)}</button><button id="worked-${id}-next" class="primary" data-worked-trace="${id}" data-direction="next">${bi(index===example.rows.length-1?g.replay:g.next)}</button></div></div></div><div class="tablewrap"><table class="worked-trace-table"><caption>${bi(g.tableTitle)}</caption><thead><tr><th scope="col">${bi(UI.line)}</th>${example.columns.map(col=>`<th scope="col">${UI[col]?bi(UI[col]):`<code>${e(col)}</code>`}</th>`).join('')}</tr></thead><tbody id="worked-${id}-rows">${workedTraceRows(example)}</tbody></table></div><p class="hint">${bi(g.legend)}</p><div class="band">${bi(example.conclusion)}</div></section>`;}
function changeWorkedTrace(id,direction){const example=TRACE_TEACHING.examples.find(item=>item.id===id);if(!example)return;const last=example.rows.length-1;workedTraceSteps[id]=direction==='back'?Math.max(0,workedTraceSteps[id]-1):workedTraceSteps[id]===last?0:workedTraceSteps[id]+1;document.querySelector(`#worked-${id}-code`).innerHTML=workedTraceCode(example);document.querySelector(`#worked-${id}-rows`).innerHTML=workedTraceRows(example);document.querySelector(`#worked-${id}-explanation`).innerHTML=workedTraceExplanation(example);document.querySelector(`#worked-${id}-output`).innerHTML=workedTraceOutput(example);document.querySelector(`#worked-${id}-back`).disabled=workedTraceSteps[id]===0;document.querySelector(`#worked-${id}-next`).innerHTML=bi(workedTraceSteps[id]===last?TRACE_TEACHING.replay:TRACE_TEACHING.next);}
function traceTeaching(){return `<section class="panel"><h2>${bi(TRACE_TEACHING.title)}</h2><p>${bi(TRACE_TEACHING.intro)}</p><div class="band">${bi(TRACE_TEACHING.tableGuide)}</div></section>`+TRACE_TEACHING.examples.map(workedTraceExample).join('');}

function tracesPage(){return pageHead('traces',B('Be the program. One line at a time.','Jadi atur cara. Satu baris pada satu masa.','扮演程序，一次执行一行。'),TRACE_INTRO)+traceTeaching()+`<section class="panel"><h2>${bi(SEQUENCE.title)}</h2><p>${bi(SEQUENCE.prompt)}</p><div class="sequence">${SEQUENCE.lines.map((code,i)=>`<label for="seq${i}"><select id="seq${i}" data-field="seq${i}" aria-label="${e(text(B('Position for ','Kedudukan bagi ','语句顺序：'))+code)}"><option value="">${e(text(UI.choose))}</option>${['1','2','3'].map(n=>`<option ${val('seq'+i)===n?'selected':''}>${n}</option>`).join('')}</select><code>${e(code)}</code></label>`).join('')}</div><div class="actions"><button data-sequence>${bi(UI.check)}</button></div>${state.checked.sequence?`<div class="feedback">${bi(SEQUENCE.answers.every((x,i)=>val('seq'+i)===x)?UI.correct:UI.rethink)}<p>${bi(SEQUENCE.why)}</p></div>`:''}</section>`+TRACES.map(tracePanel).join('');}
function counts(prefix,area,options){const out=Object.fromEntries([...options.map(x=>x[0]),'blank'].map(x=>[x,0]));TOPICS.filter(t=>t.area===area).forEach(t=>out[val(prefix+t.id)||'blank']++);return out;}
function summary(prefix,options){return `<div class="panel"><h2>${bi(B('Your six checks','Enam semakan anda','你的六项检查'))}</h2>${['knowledge','skills','understanding'].map(area=>{const c=counts(prefix,area,options);return `<p><strong>${bi(UI[area])} · 2</strong></p><div class="meter">${options.map(([k,l])=>`<span>${e(text(l))}: ${c[k]}/2</span>`).join('')}<span>${e(text(B('Not checked','Belum disemak','尚未检查')))}: ${c.blank}/2</span></div>`;}).join('')}<p class="hint" style="margin-top:1rem">${bi(UI.summary)}</p></div>`;}
function topicAction(topic,phase){const i=phase==='treading'?2:phase==='drowning'?3:phase==='consolidating'?1:0;return topic.actions[i];}
function startingNeeds(){
 const areas=['knowledge','skills','understanding'].map(area=>{const c=counts('start_',area,START_OPTIONS);return {area,develop:c.supported+c.new,prior:c.prior,pending:c.unchecked+c.blank};});
 const highest=Math.max(...areas.map(a=>a.develop));
 return {areas,highest,leaders:highest?areas.filter(a=>a.develop===highest).map(a=>a.area):[],pending:areas.reduce((sum,a)=>sum+a.pending,0)};
}
function startingGuidance(){
 const result=startingNeeds();
 const join=lang=>result.leaders.map(area=>UI[area][lang]).join(lang==='zh'?'、':', ');
 const heading=B('What do these numbers suggest for today?','Apakah cadangan daripada nombor ini untuk hari ini?','这些数字提示今天应重点学习什么？');
 let message;
 if(!result.highest&&result.pending){
 message=B('There is not enough evidence yet to suggest your main learning focus. Revisit the starter for the unchecked statements. Keep anything you already know independently as a strength; do not count “not sure” as a wrong answer.','Bukti belum mencukupi untuk mencadangkan fokus utama. Rujuk tugas permulaan bagi pernyataan yang belum disemak. Kekalkan perkara yang sudah diketahui secara kendiri sebagai kekuatan; jangan kira “tidak pasti” sebagai jawapan salah.','目前还没有足够证据推荐主要学习重点。请回看诊断题，检查尚未确认的项目。已能独立完成的内容是优势；“不确定”不算答错。');
 }else if(!result.highest){
 message=B('You marked all six checks as things you already knew or could do independently. These are strengths. Your next focus can be deeper application: change an operator, trace the effect and justify the advice. Choose the check where that challenge would help you progress.','Anda menandakan keenam-enam semakan sebagai sudah tahu atau boleh buat secara kendiri. Ini kekuatan anda. Fokus seterusnya boleh berupa aplikasi lebih mendalam: ubah operator, jejak kesannya dan justifikasikan nasihat. Pilih semakan yang cabarannya membantu anda maju.','六项都标为已经知道或能独立完成，这些是你的优势。下一步可以深入应用：改变运算符、跟踪影响并解释建议。选择能通过这一挑战继续进步的项目。');
 }else if(result.leaders.length===1){
 message=B(`Your suggested main focus is ${join('en')}. This area has the highest number of checks marked “new to me” or “with support”: ${result.highest} out of 2. Those are the things you have identified as needing development, rather than what you already know independently.`, `Fokus utama yang dicadangkan ialah ${join('ms')}. Bidang ini mempunyai bilangan tertinggi semakan “baharu bagi saya” atau “dengan sokongan”: ${result.highest} daripada 2. Inilah perkara yang anda kenal pasti perlu ditingkatkan, berbanding perkara yang sudah dikuasai secara kendiri.`, `建议主要关注${join('zh')}。这一方面标为“新内容”或“需要支持”的项目最多：2 项中有 ${result.highest} 项。这些是你自己指出需要提高的内容，已经能独立完成的项目则属于已有优势。`);
 }else{
 message=B(`Your suggested focus areas are ${join('en')}. They are tied: each has ${result.highest} out of 2 checks marked “new to me” or “with support”. You may develop more than one type of learning today. Start with the specific check your starter evidence shows you most need to improve.`, `Bidang fokus yang dicadangkan ialah ${join('ms')}. Bilangannya sama: setiap satu mempunyai ${result.highest} daripada 2 semakan “baharu bagi saya” atau “dengan sokongan”. Anda boleh mengembangkan lebih daripada satu jenis pembelajaran hari ini. Mulakan dengan semakan khusus yang bukti tugas permulaan menunjukkan paling perlu ditingkatkan.`, `建议关注${join('zh')}，它们并列最高：每个方面的 2 项中都有 ${result.highest} 项为“新内容”或“需要支持”。今天可以发展多个学习类型。先根据诊断答案的证据，选择最需要提高的具体项目。`);
 }
 const meanings={knowledge:B('Build knowledge: clarify the meanings of data types, assignment and operators. Then recall them without the guide.','Bina pengetahuan: jelaskan makna jenis data, penugasan dan operator. Kemudian ingat semula tanpa panduan.','发展知识：弄清数据类型、赋值与运算符的含义，再不看指南回忆。'),skills:B('Practise skills: write valid assignments and follow a trace accurately. Repeat with new values and gradually use less support.','Latih kemahiran: tulis penugasan sah dan ikuti jejak dengan tepat. Ulang dengan nilai baharu dan kurangkan sokongan secara beransur-ansur.','练习技能：正确编写赋值、准确跟踪程序。换一组数值再试，并逐渐减少提示。'),understanding:B('Develop understanding: explain why a data choice or operator suits the purpose. Use a specific message or trace to justify how the advice changes.','Kembangkan pemahaman: jelaskan mengapa pilihan data atau operator sesuai dengan tujuan. Gunakan mesej atau jejak tertentu untuk menjustifikasikan perubahan nasihat.','加深理解：解释数据或运算符的选择为什么适合目的，用具体消息或跟踪结果说明建议如何改变。')};
 const targets=TOPICS.filter(t=>result.leaders.includes(t.area)&&['new','supported'].includes(val('start_'+t.id)));
 return `<section class="panel focus-guidance" aria-labelledby="focusGuidanceTitle"><h2 id="focusGuidanceTitle">${bi(heading)}</h2><p class="hint">${bi(B('We count “new to me” + “with support” to find where you currently see the most need to improve. Each area has two checks. This is a suggested focus from your self-check, not a test score.','Kami mengira “baharu bagi saya” + “dengan sokongan” untuk mengenal pasti keperluan peningkatan terbesar yang anda lihat sekarang. Setiap bidang mempunyai dua semakan. Ini cadangan fokus daripada semakan kendiri, bukan markah ujian.','将“新内容”与“需要支持”的数量相加，找出你目前认为最需要提高的方面。每个方面有两项。这是根据自查提出的建议，不是考试分数。'))}</p><div class="meter">${result.areas.map(a=>`<span>${bi(UI[a.area])}: ${a.develop}/2</span>`).join('')}</div><div class="band">${bi(message)}</div>${result.highest&&result.pending?`<p>${bi(B(`${result.pending} of the six checks are still unsure or unchecked, so this suggestion is provisional. Review those checks before settling on your focus.`, `Sebanyak ${result.pending} daripada enam semakan masih tidak pasti atau belum disemak, jadi cadangan ini sementara. Semak perkara tersebut sebelum menetapkan fokus.`, `六项中仍有 ${result.pending} 项不确定或未检查，因此这只是暂时建议。确定重点前，请先回看这些项目。`))}</p>`:''}${result.leaders.map(area=>`<p><strong>${bi(UI[area])}</strong><br>${bi(meanings[area])}</p>`).join('')}${targets.length?`<h3>${bi(B('Turn this into a specific next step','Jadikan ini langkah seterusnya yang khusus','把建议变成具体下一步'))}</h3><ul>${targets.map(t=>`<li><strong>${bi(t.title)}</strong><br>${bi(topicAction(t,val('start_'+t.id)==='supported'?'consolidating':'new'))}</li>`).join('')}</ul><p>${bi(B('Use the focus selector below to choose one of these checks, or another check if your work gives a stronger reason. Cite a starter answer and explain your choice. This supports the WAGBA: choosing suitable data and operators, then tracing and explaining the result.','Gunakan pemilih fokus di bawah untuk memilih salah satu semakan ini, atau semakan lain jika kerja anda memberi sebab lebih kukuh. Rujuk jawapan permulaan dan jelaskan pilihan. Ini menyokong WAGBA: memilih data dan operator sesuai, kemudian menjejak dan menerangkan hasil.','在下方选择一个具体重点；如果作品提供更有力的理由，也可以选择其他项目。引用诊断答案并解释选择。这将帮助实现 WAGBA：选择合适的数据与运算符，跟踪并解释结果。'))}</p>`:''}</section>`;
}
function pitPattern(){const totals=Object.fromEntries(PHASE_OPTIONS.map(([key])=>[key,0]));let blank=0;for(const topic of TOPICS){const phase=val('phase_'+topic.id);if(phase in totals)totals[phase]++;else blank++;}const phases=PHASE_OPTIONS.filter(([key])=>key!=='unattempted');const assessed=phases.reduce((n,[key])=>n+totals[key],0),highest=Math.max(...phases.map(([key])=>totals[key]));return {totals,blank,assessed,highest,leaders:highest?phases.filter(([key])=>totals[key]===highest).map(([key])=>key):[]};}
function pitGuidance(){const r=pitPattern(),names=lang=>r.leaders.map(key=>PHASE_OPTIONS.find(([id])=>id===key)[1][lang]).join(' / ');let message=PIT_SUMMARY.empty;
 if(r.leaders.length===1){message=B(`${names('en')} is your most selected phase: ${r.highest} of ${r.assessed} phase choices.`,`${names('ms')} ialah fasa paling banyak dipilih: ${r.highest} daripada ${r.assessed} pilihan fasa.`,`${names('zh')}是你选择最多的阶段：${r.assessed} 项阶段选择中有 ${r.highest} 项。`);}
 else if(r.leaders.length>1)message=B(`Your highest counts are tied: ${names('en')}, with ${r.highest} of ${r.assessed} phase choices each. There is no single leading phase. Your learning is mixed across these areas.`,`Bilangan tertinggi seri: ${names('ms')}, masing-masing ${r.highest} daripada ${r.assessed} pilihan fasa. Tiada satu fasa utama. Pembelajaran anda bercampur antara bidang ini.`,`最高数量并列：${names('zh')}，各占 ${r.assessed} 项阶段选择中的 ${r.highest} 项。没有单一领先阶段，你在不同方面的学习体验有所不同。`);
 const helped=TOPICS.filter(t=>val('phase_'+t.id)==='drowning');
 return `<section class="panel pit-pattern" aria-labelledby="pitPatternTitle"><h2 id="pitPatternTitle">${bi(PIT_SUMMARY.title)}</h2><p>${bi(PIT_SUMMARY.intro)}</p><div class="phase-totals">${PHASE_OPTIONS.filter(([key])=>key!=='unattempted').map(([key,label])=>`<div class="phase-total ${r.leaders.includes(key)?'leading-phase':''}"><strong>${bi(label)}</strong><span class="phase-count">${r.totals[key]} / 6</span><div class="phase-track" aria-hidden="true"><span style="width:${r.totals[key]/6*100}%"></span></div></div>`).join('')}</div><div class="band" role="status" aria-live="polite">${bi(message)}</div>
 ${r.leaders.length===1&&r.assessed?`<p>${bi(r.highest>r.assessed/2?B('This is a majority of the checks where you chose a phase.','Ini majoriti semakan yang mempunyai pilihan fasa.','这占已选择阶段项目的多数。'):B('This is the highest count, but not more than half of your phase choices. The other experiences still matter.','Ini bilangan tertinggi, tetapi tidak melebihi separuh pilihan fasa. Pengalaman lain masih penting.','这是最高数量，但没有超过阶段选择的一半，其他体验仍然重要。'))}</p>`:''}
 <p class="hint">${bi(B(`Not attempted: ${r.totals.unattempted}/6. Not selected: ${r.blank}/6. These do not count as a learning phase.`,`Belum dicuba: ${r.totals.unattempted}/6. Belum dipilih: ${r.blank}/6. Ini tidak dikira sebagai fasa pembelajaran.`,`尚未尝试：${r.totals.unattempted}/6。尚未选择：${r.blank}/6。这些不计入学习阶段。`))}</p>
 ${r.assessed<6&&r.assessed?`<p>${bi(B('This is a provisional picture of the checks you have rated so far. Complete any remaining checks you have attempted.','Ini gambaran sementara semakan yang dinilai setakat ini. Lengkapkan semakan lain yang telah dicuba.','这只是目前已评价项目的暂时结果，请补全其他已尝试项目的评价。'))}</p>`:''}
 ${r.leaders.map(key=>`<p class="phase-meaning">${bi(REFLECT.phaseGuides[['new','consolidating','treading','drowning'].indexOf(key)])}</p>`).join('')}
 ${helped.length?`<div class="pit-help"><h3>${bi(PIT_SUMMARY.help)}</h3><ul>${helped.map(t=>`<li><strong>${bi(t.title)}</strong><br>${bi(topicAction(t,'drowning'))}</li>`).join('')}</ul></div>`:''}
 <p>${bi(PIT_SUMMARY.evidence)}</p><p>${bi(PIT_SUMMARY.next)}</p></section>`;
}
function reflection(pit){const id=pit?'pit':'types',prefix=pit?'phase_':'start_',options=pit?PHASE_OPTIONS:START_OPTIONS;let html=pageHead(id,null,pit?REFLECT.pitIntro:REFLECT.typesIntro)+`<div class="band"><strong>WAGBA</strong><div>${bi(LESSON.wagba)}</div></div>`;
 html+=pit?`<div class="phase-grid">${REFLECT.phaseGuides.map(g=>`<p>${bi(g)}</p>`).join('')}</div><p class="hint">${bi(B('If you have not tried a check, select “Not attempted yet”. No phase is assigned automatically from correct answers.','Jika belum mencuba semakan, pilih “Belum dicuba”. Tiada fasa ditetapkan secara automatik berdasarkan jawapan betul.','尚未尝试的项目请选择“尚未尝试”。答对与否不会自动决定学习阶段。'))}</p><div class="band"><strong>${bi(REFLECT.focus)}:</strong> ${val('start_focus')?bi(TOPICS.find(t=>t.id===val('start_focus')).title):bi(UI.notAnswered)}${val('start_note')?`<p>${e(val('start_note'))}</p>`:''}</div>`:`<section class="panel"><p>${bi(REFLECT.typesExplain)}</p></section>`;
 html+=`<section class="panel">${TOPICS.map(topic=>`<div class="topic"><div class="topic-head"><span class="badge">${e(topic.id.toUpperCase())}</span><div><h3>${bi(topic.title)}</h3><p class="hint">${bi(pit?topic.end:topic.start)}</p></div></div>${pit?`<p class="hint"><strong>${bi(UI.start)}:</strong> ${bi(START_OPTIONS.find(o=>o[0]===val('start_'+topic.id))?.[1]||UI.notAnswered)}</p>`:''}${select(prefix+topic.id,pit?UI.phase:UI.start,options)}${pit&&val(prefix+topic.id)&&val(prefix+topic.id)!=='unattempted'?`<div class="band"><strong>${bi(UI.nextAction)}</strong><div>${bi(topicAction(topic,val(prefix+topic.id)))}</div></div>`:''}</div>`).join('')}</section>`;
 html+=pit?pitGuidance():summary(prefix,options)+startingGuidance();
 const focusId=pit?'end_focus':'start_focus',selected=TOPICS.find(t=>t.id===val(focusId));
 html+=`<section class="panel">${select(focusId)}${selected?`<div class="band"><strong>${bi(pit?UI.nextAction:UI.firstAction)}</strong><div>${bi(topicAction(selected,pit?val('phase_'+selected.id):(val('start_'+selected.id)==='prior'?'treading':val('start_'+selected.id)==='supported'?'consolidating':'new')))}</div></div>`:`<p class="hint">${bi(REFLECT.secure)}</p>`}${writing(pit?'end_note':'start_note')}<p class="hint">${bi(UI.note)}</p>${pit?`<details><summary>${bi(UI.model)}</summary><p>${bi(REFLECT.example)}</p></details>`:''}</section>`;return html;}
function challengeCell(id){return `<textarea class="challenge-answer" id="${id}" data-field="${id}" aria-label="${e(text(FIELDS.get(id).label))}" rows="3" maxlength="30000">${e(val(id))}</textarea>`;}
function challengeHeading(index){const l=CHALLENGE_LEVELS.levels[index];return `<header class="challenge-heading"><span class="level-number" aria-hidden="true">${index+1}</span><div><span class="pill">${bi(l.focus)}</span><h2>${bi(l.title)}</h2><p>${bi(l.outcome)}</p></div></header>`;}
function challengeSteps(steps){return `<ol class="task-steps">${steps.map(step=>`<li>${bi(step)}</li>`).join('')}</ol>`;}
function challengesPage(){const c=CHALLENGE_LEVELS;return pageHead('challenge',c.title,c.intro)+`
<nav class="challenge-roadmap" aria-label="${e(text(UI.challenge))}">${c.levels.map((l,i)=>`<a href="#challenge-level-${i+1}"><span class="pill">${bi(l.focus)}</span><strong>${bi(l.title)}</strong><span>${bi(l.outcome)}</span></a>`).join('')}</nav>
<section class="panel challenge-level" id="challenge-level-1">${challengeHeading(0)}<p>${bi(c.glossaryIntro)}</p>${codeLines(c.glossaryCode)}
<div class="challenge-table"><p class="narrow-table-hint hint">${bi(c.tableHint)}</p>${lessonTable([c.term,c.ownWords,c.codeEvidence],c.terms.map(([id,name,hint])=>[`<strong>${bi(name)}</strong><p class="hint">${bi(hint)}</p>`,challengeCell('c1_'+id+'_meaning'),challengeCell('c1_'+id+'_example')]),c.levels[0].outcome)}</div><div class="band">${bi(c.glossaryCheck)}</div>${val('c1')?writing('c1',c.legacy):''}</section>
<section class="panel challenge-level" id="challenge-level-2">${challengeHeading(1)}<div class="challenge-example"><h3>${bi(c.original)}</h3><ol class="tracecode lesson-code">${TRACES[2].code.map((line,i)=>`<li${i===2?' class="active"':''}><code>${e(line)}</code></li>`).join('')}</ol>${lessonTable([c.before,c.after],[[codeCell('needs_review = is_urgent or asks_password'),codeCell('needs_review = is_urgent and asks_password')]],c.changedLine)}</div>${challengeSteps(c.compareSteps)}
<div class="challenge-table"><p class="narrow-table-hint hint">${bi(c.tableHint)}</p>${lessonTable([c.caseLabel,c.orPrediction,c.andPrediction,c.actual],c.compareCases.map(([id,urgent,password])=>[`<strong>${id.toUpperCase()}</strong><pre>is_urgent = ${urgent}
asks_password = ${password}</pre>`,challengeCell('c2_'+id+'_or'),challengeCell('c2_'+id+'_and'),challengeCell('c2_'+id+'_actual')]),c.levels[1].outcome)}</div>${pythonEditor(c.tasks[0])}<div class="band">${bi(c.compareNote)}</div>${writing('c2')}</section>
<section class="panel challenge-level" id="challenge-level-3">${challengeHeading(2)}<p>${bi(c.uncertainIntro)}</p><div class="challenge-example"><h3>${bi(c.patternTitle)}</h3>${codeLines(c.pattern)}<p>${bi(c.patternNote)}</p></div>${challengeSteps(c.buildSteps)}
<div class="challenge-table"><p class="narrow-table-hint hint">${bi(c.tableHint)}</p>${lessonTable(['urgency_answer',c.advice,c.prediction,c.actual],c.testCases.map(([id,value,advice])=>[codeCell(value),bi(advice),challengeCell('c3_'+id+'_prediction'),challengeCell('c3_'+id+'_actual')]),c.levels[2].outcome)}</div>${pythonEditor(c.tasks[1])}${writing('c3')}</section>`;}
function challengeReportContext(){const c=CHALLENGE_LEVELS;return `<p>${bi(c.intro)}</p><h3>${bi(c.levels[0].title)}</h3><p>${bi(c.glossaryIntro)}</p><pre>${e(c.glossaryCode.join('\n'))}</pre><h3>${bi(c.original)}</h3><pre>${e(TRACES[2].code.join('\n'))}</pre>${challengeSteps(c.compareSteps)}<p>${bi(c.compareNote)}</p><h3>${bi(c.levels[2].title)}</h3><p>${bi(c.uncertainIntro)}</p>${challengeSteps(c.buildSteps)}${lessonTable(['urgency_answer',c.advice],c.testCases.map(([,value,advice])=>[codeCell(value),bi(advice)]),c.levels[2].outcome)}`;}

function exitActivities(){const c=EXIT_CHECKS;return `<section class="panel"><h2>${bi(c.learnedTitle)}</h2>${writing('exit_learned')}</section><section class="panel"><h2>${bi(c.typesTitle)}</h2><p>${bi(c.typesIntro)}</p><div class="challenge-table"><p class="narrow-table-hint hint">${bi(CHALLENGE_LEVELS.tableHint)}</p>${lessonTable([c.situation,c.type,c.assignment,c.reason],c.rows.map(([id,situation])=>[bi(situation),challengeCell('exit_'+id+'_type'),challengeCell('exit_'+id+'_assignment'),challengeCell('exit_'+id+'_reason')]),c.typesTitle)}</div>${writing('exit_boolean')}</section><section class="panel"><h2>${bi(c.constantsTitle)}</h2><p>${bi(c.constantsIntro)}</p><div class="exit-code">${writing('exit_constants_code')}</div>${writing('exit_constants_explain')}<div class="band">${bi(c.check)}</div></section>${PLENARY.questions.some(q=>val(q.id))?`<section class="panel"><h2>${bi(c.legacy)}</h2><pre class="code">${e(PLENARY.code.join('\n'))}</pre>${PLENARY.questions.filter(q=>val(q.id)).map(q=>`<p><strong>${bi(q.prompt)}</strong><br>${bi(formatted(q.id,val(q.id)))}</p>`).join('')}</section>`:''}`;}
function exitReportContext(){return `<p>${bi(EXIT_CHECKS.intro)}</p><h3>${bi(EXIT_CHECKS.typesTitle)}</h3><p>${bi(EXIT_CHECKS.typesIntro)}</p><h3>${bi(EXIT_CHECKS.constantsTitle)}</h3><p>${bi(EXIT_CHECKS.constantsIntro)}</p>${PLENARY.questions.some(q=>val(q.id))?`<h3>${bi(EXIT_CHECKS.legacy)}</h3><pre>${e(PLENARY.code.join('\n'))}</pre>`:''}`;}
function submitPage(){return pageHead('submit',EXIT_CHECKS.title,EXIT_CHECKS.intro)+exitActivities()+`<section class="panel"><h2>${bi(B('Save, check, submit','Simpan, semak, hantar','保存、检查、提交'))}</h2><p>${bi(PLENARY.checklist)}</p><label class="field" for="name"><span>${bi(UI.name)}</span><input class="report-name" id="name" data-field="name" value="${e(val('name'))}" maxlength="120" autocomplete="off"></label><ol>${PLENARY.steps.map(s=>`<li>${bi(s)}</li>`).join('')}</ol><button class="primary" data-pdf>${bi(UI.pdf)}</button><details><summary>${bi(UI.other)}</summary><p>${bi(PLENARY.options)}</p><div class="actions"><button data-backup>${bi(UI.backup)}</button><button data-report>${bi(UI.readable)}</button><button data-restore>${bi(UI.restore)}</button><input type="file" id="restoreFile" accept=".json,application/json" hidden></div></details><p class="hint">${bi(B('Work is saved only in this browser on this device. Save a copy before changing device, clearing browser data or leaving a shared computer.','Kerja disimpan hanya dalam pelayar pada peranti ini. Simpan salinan sebelum menukar peranti, memadam data pelayar atau meninggalkan komputer dikongsi.','作业仅保存在此设备的当前浏览器中。更换设备、清除浏览器数据或离开共用电脑前，请保存副本。'))}</p></section>`;}
const renderers=[reading,starter,()=>reflection(false),dataPage,operatorsPage,tracesPage,challengesPage,()=>reflection(true),submitPage];
function hasSavedWork(){return Object.entries(state.answers).some(([id,value])=>!['name','student_name','student_class'].includes(id)&&value.trim())||Object.keys(state.first).length>0||Object.keys(state.models).length>0||Object.keys(state.walks).length>0;}
function learningFocus(){
 if(!entryVisible&&SUPPORTED.active())return SUPPORTED.learning();
 const goalBody=g=>Object.fromEntries(Object.entries(g).map(([lang,value])=>[lang,value.includes(' · ')?value.split(' · ').slice(1).join(' · '):value]));
 return `<section class="learning-focus" aria-labelledby="learningFocusTitle"><h2 id="learningFocusTitle">${bi(B('Today’s learning','Pembelajaran hari ini','今天的学习'))}</h2><dl><div class="wagba-focus"><dt>WAGBA</dt><dd>${bi(LESSON.wagba)}</dd></div>${['knowledge','skills','understanding'].map((area,i)=>`<div><dt>${bi(UI[area])}</dt><dd>${bi(goalBody(LESSON.goals[i]))}</dd></div>`).join('')}</dl></section>`;
}
function lessonNavigation(){return `<nav class="lesson-nav" aria-label="${e(text(UI.notebook))}">${PAGES.map(([id],i)=>`<button data-page="${i}" ${i===state.page?'aria-current="step"':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span>${bi(UI[id])}</span></button>`).join('')}</nav>`;}
function renderEntry(){
 document.documentElement.lang=state.lang==='zh'?'zh-Hans':state.lang;
 document.title=text(UI.year)+' · '+text(LESSON.title);
 document.querySelector('.skip').textContent=text(B('Skip to your notebook','Langkau ke buku catatan','跳到学习记录'));
 const existing=hasSavedWork();
 document.querySelector('#app').innerHTML=`<main class="entry-shell" id="main" tabindex="-1"><section class="entry-intro"><p class="eyebrow">${e(text(UI.year))} · ${e(text(ENTRY.duration))}</p><h1>${e(text(ENTRY.title))}</h1><p class="entry-lede">${e(text(ENTRY.intro))}</p><div class="entry-outcome"><strong>${e(text(ENTRY.outcomeLabel))}</strong><p>${e(text(ENTRY.outcome))}</p></div>${learningFocus()}<p class="caption" style="color:#c8ded5;margin-top:2rem">${e(text(ENTRY.route))}</p></section><section class="entry-form-wrap"><form class="entry-form" id="entryForm" novalidate><p class="eyebrow">${e(text(LESSON.title))}</p><h2>${e(text(ENTRY.notebook))}</h2><div class="entry-fields"><label class="field" for="entryName"><span>${e(text(ENTRY.fullName))}</span><input id="entryName" name="studentName" autocomplete="name" maxlength="100" value="${e(entryDraft.name)}" required ${entryError&&!entryDraft.name.trim()?'aria-invalid="true" aria-describedby="entryError"':''}></label><label class="field" for="entryClass"><span>${e(text(ENTRY.className))}</span><input id="entryClass" name="studentClass" autocomplete="off" maxlength="30" value="${e(entryDraft.className)}" required ${entryError&&!entryDraft.className.trim()?'aria-invalid="true" aria-describedby="entryError"':''}></label></div><label class="field" for="entryLanguage"><span>${e(text(ENTRY.language))}</span><select id="entryLanguage">${[['en','English'],['ms','Bahasa Melayu'],['zh','简体中文']].map(([v,label])=>`<option value="${v}" ${state.lang===v?'selected':''}>${label}</option>`).join('')}</select></label><p class="hint">${e(text(ENTRY.languageNote))}</p>${existing?`<div class="band">${e(text(ENTRY.savedNote))}</div>`:''}<p class="entry-error" id="entryError" role="alert">${entryError?e(text(ENTRY.required)):''}</p><button class="primary" type="submit">${e(text(existing?ENTRY.beginning:ENTRY.begin))}</button>${existing?`<button class="resume-button" type="button" data-resume>${e(text(ENTRY.resume))}</button>`:''}<p class="entry-privacy">${e(text(storageOK?ENTRY.privacy:UI.saveError))}</p></form></section></main>`;
}
function stopNotebookRun(){if(pythonWorker)pythonWorker.terminate();clearTimeout(pythonTimer);pythonWorker=null;pythonBusy=null;}
function switchNotebook(name){const target=STORAGE+(SUPPORTED.matches(name)?'-guided':'');if(target===activeStorage)return;save();stopNotebookRun();activeStorage=target;state=fresh();try{const stored=localStorage.getItem(target);if(stored)state=validate(JSON.parse(stored));}catch{storageOK=false;}updateStep=0;}
function enterLesson(resume=false){
 entryDraft.name=entryDraft.name.trim();entryDraft.className=entryDraft.className.trim();
 if(!entryDraft.name||!entryDraft.className){entryError=true;renderEntry();document.querySelector(!entryDraft.name?'#entryName':'#entryClass').focus();return false;}
 switchNotebook(entryDraft.name);
 state.answers.student_name=entryDraft.name;state.answers.student_class=entryDraft.className;state.answers.name=entryDraft.name+' · '+entryDraft.className;
 entryError=false;entryVisible=false;if(!resume)state.page=0;save();render();return true;
}
function showWelcome(){entryDraft={name:val('student_name')||val('name'),className:val('student_class')};entryError=false;entryVisible=true;save();renderEntry();window.scrollTo(0,0);}
document.addEventListener('submit',event=>{if(event.target.id==='entryForm'){event.preventDefault();enterLesson(false);}});
function render(keep=false){if(entryVisible){renderEntry();return;}const active=document.activeElement?.id,selection=document.activeElement?.selectionStart,scroll=window.scrollY;document.documentElement.lang=state.lang==='zh'?'zh-Hans':state.lang;document.title=text(UI.year)+' · '+text(LESSON.title);document.querySelector('.skip').textContent=text(B('Skip to lesson','Langkau ke pelajaran','跳到课程'));document.querySelector('#app').innerHTML=`${teacher?`<div class="teacher">${bi(UI.teacher)}</div>`:''}<div class="shell"><aside class="sidebar"><p class="eyebrow">${bi(UI.year)}</p><div class="brand">${bi(LESSON.title)}</div><p class="caption" style="color:#c7dad4">${bi(UI.theory)}</p>${learningFocus()}</aside><div class="lesson-column"><header class="topbar"><div class="save" id="saveStatus" role="status">${bi(storageOK?UI.saved:UI.saveError)}</div><div class="toolbar">${val('name')?`<span class="identity">${e(val('name'))}</span>`:''}<button class="welcome-button" data-welcome>${e(text(ENTRY.welcome))}</button><label>${e(text(UI.language))}<select id="language"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="ms" ${state.lang==='ms'?'selected':''}>Bahasa Melayu</option><option value="zh" ${state.lang==='zh'?'selected':''}>简体中文</option></select></label><label>${e(text(UI.mode))}<select id="viewMode"><option value="focus" ${state.mode==='focus'?'selected':''}>${e(text(UI.focus))}</option><option value="compare" ${state.mode==='compare'?'selected':''}>${e(text(UI.compare))}</option></select></label></div></header>${lessonNavigation()}<main id="main" tabindex="-1">${SUPPORTED.active()?SUPPORTED.renderPage(state.page):renderers[state.page]()}<footer class="stepfooter"><button data-page="${state.page-1}" ${state.page===0?'disabled':''}>${SUPPORTED.active()?'Previous section / 上一节':bi(UI.back)}</button><span class="hint">${state.page+1} / ${PAGES.length}</span><button class="primary" data-page="${state.page+1}" ${state.page===PAGES.length-1?'disabled':''}>${SUPPORTED.active()?'Next section / 下一节':bi(UI.next)}</button></footer><div class="source">${bi(B('Python examples use Python 3. Reading reference:','Contoh Python menggunakan Python 3. Rujukan bacaan:','示例使用 Python 3。阅读参考：'))} <a href="https://docs.python.org/3/tutorial/introduction.html" target="_blank" rel="noopener">Python — An Informal Introduction</a></div></main></div></div>`;if(keep){if(active){const el=document.getElementById(active);el?.focus({preventScroll:true});if(typeof selection==='number'&&el?.setSelectionRange)el.setSelectionRange(selection,selection);}window.scrollTo(0,scroll);}else{window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});}bindDetails();}
function go(page){if(!Number.isInteger(page)||page<0||page>=PAGES.length)throw Error('Invalid page');state.page=page;entryVisible=false;save();render();}
function bindDetails(){document.querySelectorAll('details[data-model]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open&&!state.models[d.dataset.model]){const id=d.dataset.model;remember(id);state.models[id]=true;save();}}));}
function formatted(id,v){const f=FIELDS.get(id);return f?.options?.find(o=>o[0]===v)?.[1]||v;}
function reportBody(){if(SUPPORTED.active())return SUPPORTED.report();const sections=[
 [UI.starter,STARTER.flatMap(q=>[q.id,q.id+'_support'])],
 [UI.types,[...TOPICS.map(t=>'start_'+t.id),'start_focus','start_note']],
 [UI.data,['d1','d2','d3','d4_code','d4',...DATA_ANNOTATION_IDS,'d5']],
 [UI.operators,[...OPS.questions.slice(0,6).map(q=>q.id),...OPERATOR_RESPONSE_IDS]],
 [UI.traces,[...SEQUENCE.lines.map((_,i)=>'seq'+i),...TRACES.flatMap(t=>[...t.rows.flatMap(([line])=>t.columns.map(c=>`${t.id}_${line}_${c}`)),t.id+'_explain',t.id+'_support'])]],
 [UI.challenge,[...(val('c1')?['c1']:[]),...CHALLENGE_RESPONSE_IDS,'c2','c3']],
 [UI.pit,[...TOPICS.map(t=>'phase_'+t.id),'end_focus','end_support','end_note']],
 [UI.submit,[...EXIT_RESPONSE_IDS,...PLENARY.questions.filter(q=>val(q.id)).map(q=>q.id)]]];
 return `<h1>${bi(UI.report)}</h1><p><strong>${e(val('name')||text(UI.notAnswered))}</strong></p><p>${e(new Date().toLocaleString())}${teacher?' · '+e(text(UI.teacher)):''}</p><div class="band"><strong>WAGBA</strong><div>${bi(LESSON.wagba)}</div></div><p>${bi(UI.summary)}</p>${sections.map(([title,ids])=>`<section class="panel"><h2>${bi(title)}</h2>${title===UI.operators?`<h3>${bi(OP_GUIDE.q7Title)}</h3><p>${bi(OP_GUIDE.q7Prompt)}</p><pre>${e(OP_GUIDE.q7Or.join('\n'))}</pre><pre>${e(OP_GUIDE.q7And.join('\n'))}</pre>${OP_GUIDE.tasks.map(t=>`<h3>${bi(t.title)}</h3><p>${bi(t.prompt)}</p><p>${bi(t.follow)}</p>`).join('')}`:''}${title===UI.challenge?challengeReportContext():''}${title===UI.data?`<h3>${bi(DATA_GUIDE.d4Title)}</h3><p>${bi(DATA_GUIDE.d4Prompt)}</p><pre>2 links = 3</pre><h3>${bi(DATA_GUIDE.d5Title)}</h3><p>${bi(DATA_GUIDE.d5Prompt)}</p><pre>${e(DATA_GUIDE.d5Code.join('\n'))}</pre>`:''}${title===UI.pit?pitGuidance():''}${title===UI.submit?exitReportContext():''}${title===UI.traces?TRACES.map(t=>`<h3>${bi(t.title)}</h3><pre>${e(t.code.map((l,i)=>`${i+1}  ${l}`).join('\n'))}</pre>`).join(''):''}${ids.filter(id=>!id.endsWith('_support')).map(id=>`<div class="report-item"><strong>${bi(FIELDS.get(id).label)}</strong><div class="report-answer">${val(id)?bi(formatted(id,val(id))):bi(UI.notAnswered)}</div>${state.models[id]?`<p class="hint">${bi(B('Example viewed','Contoh dilihat','已查看示例'))}</p>`:''}${state.checked[id]?`<p class="hint">${bi(B('Answer feedback viewed','Maklum balas jawapan dilihat','已查看答案反馈'))}</p>`:''}</div>`).join('')}</section>`).join('')}<section><h2>${bi(B('First recorded attempts before feedback','Cubaan pertama direkod sebelum maklum balas','查看反馈前首次记录的尝试'))}</h2><p>${bi(B('These snapshots preserve the answer present when feedback or a walkthrough was first opened. They do not prove independent work.','Petikan ini mengekalkan jawapan semasa maklum balas atau panduan mula dibuka. Ia tidak membuktikan kerja kendiri.','这些记录保留首次打开反馈或演示时的答案，但不能证明独立完成。'))}</p>${Object.entries(state.first).map(([id,entry])=>`<div class="report-item"><strong>${e(id)}</strong>${Object.entries(entry.values).map(([key,value])=>`<p>${bi(FIELDS.get(key)?.label||key)}: <span class="report-answer">${value?bi(formatted(key,value)):bi(UI.notAnswered)}</span></p>`).join('')}</div>`).join('')||`<p>${bi(UI.notAnswered)}</p>`}</section>`;}
function download(name,type,data){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function filename(ext){return 'Year9-Week3-'+(val('name').trim().replace(/[^\p{L}\p{N}_-]/gu,'-').slice(0,70)||'learning-record')+'.'+ext;}
function exportHTML(){return '<!doctype html><html lang="'+(state.lang==='zh'?'zh-Hans':state.lang)+'"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(text(UI.report))+'</title><style>body{font:16px/1.6 Arial,sans-serif;max-width:1000px;margin:auto;padding:30px;color:#16332d}.report-item{padding:12px 0;border-bottom:1px solid #ccd6d4;break-inside:avoid}.report-answer,pre{white-space:pre-wrap;overflow-wrap:anywhere}.hint{font-size:14px;color:#405a56}.compare{display:grid;grid-template-columns:1fr 1fr;gap:20px}h2{border-bottom:2px solid #075c49;padding-top:24px}.band{background:#eef5f1;padding:15px}@media(max-width:600px){.compare{display:block}}@media print{@page{margin:16mm}body{font-size:10pt;padding:0}}</style><body>'+reportBody()+'</body></html>';}
document.addEventListener('input',event=>{if(event.target.id==='entryName')entryDraft.name=event.target.value;if(event.target.id==='entryClass')entryDraft.className=event.target.value;const id=event.target.dataset.field;if(id){const hadFeedback=state.checked[id]||TRACES.some(t=>id.startsWith(t.id+'_')&&state.checked[t.id]);setAnswer(id,event.target.value);if(PYTHON_TASKS.some(t=>id===t.id+'_code'))refreshPythonOutputs();if(event.target.type==='radio'||hadFeedback)render(true);}});
document.addEventListener('change',async event=>{const target=event.target;if(target.id==='entryLanguage'){state.lang=target.value;save();renderEntry();document.querySelector('#entryLanguage').focus();}else if(target.id==='language'){state.lang=target.value;save();render(true);}else if(target.id==='viewMode'){state.mode=target.value;save();render(true);}else if(target.dataset.field&&target.tagName==='SELECT'){setAnswer(target.dataset.field,target.value);if(/^(start_|phase_|end_focus|g_start_|g_now_|g_phase_|g_end_)/.test(target.dataset.field))render(true);}else if(target.id==='restoreFile'&&target.files[0]){const file=target.files[0];try{if(file.size>2500000)throw Error('Too large');const restored=validate(JSON.parse(await file.text()));download(filename('before-restore.json'),'application/json',JSON.stringify(state,null,2));stopNotebookRun();activeStorage=STORAGE+(SUPPORTED.matches(restored.answers.student_name||restored.answers.name)?'-guided':'');state=restored;entryDraft={name:state.answers.student_name||state.answers.name||'',className:state.answers.student_class||''};save();render();toast(B('Backup restored. A copy of your previous work was downloaded first.','Sandaran dipulihkan. Salinan kerja sebelumnya dimuat turun dahulu.','备份已恢复，之前的作业已先下载保存。'));}catch{toast(B('This file could not be restored. Choose a Year 9 Week 3 full backup. Your work has not changed.','Fail ini tidak dapat dipulihkan. Pilih sandaran penuh Tahun 9 Minggu 3. Kerja anda tidak berubah.','无法恢复此文件。请选择九年级第3周完整备份。现有作业未改变。'));}target.value='';}});
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(SUPPORTED.handleClick(b))return;if(b.dataset.workedTrace){changeWorkedTrace(b.dataset.workedTrace,b.dataset.direction);return;}if(b.dataset.pythonRun){runPythonTask(b.dataset.pythonRun);return;}if(b.hasAttribute('data-resume')){enterLesson(true);return;}if(b.hasAttribute('data-welcome')){showWelcome();return;}if(b.dataset.page!==undefined)go(Number(b.dataset.page));else if(b.hasAttribute('data-memory')){changeUpdateStep(updateStep===3?0:updateStep+1);}else if(b.hasAttribute('data-update-back')){changeUpdateStep(updateStep-1);}else if(b.dataset.check){const q=ALL_QUESTIONS.find(q=>q.id===b.dataset.check);if(!val(q.id)){toast(UI.answerFirst);return;}remember(q.id);state.checked[q.id]=true;save();render(true);}else if(b.dataset.walk){const t=TRACES.find(t=>t.id===b.dataset.walk);remember(t.id,t.rows.flatMap(([line])=>t.columns.map(col=>`${t.id}_${line}_${col}`)));state.walks[t.id]=Math.min(t.steps.length,(state.walks[t.id]||0)+1);save();render(true);}else if(b.dataset.restart){state.walks[b.dataset.restart]=0;save();render(true);}else if(b.dataset.traceCheck){const t=TRACES.find(t=>t.id===b.dataset.traceCheck);if(!traceResult(t).attempted){toast(UI.answerFirst);return;}remember(t.id,t.rows.flatMap(([line])=>t.columns.map(col=>`${t.id}_${line}_${col}`)));state.checked[t.id]=true;save();render(true);}else if(b.hasAttribute('data-sequence')){if(!SEQUENCE.lines.every((_,i)=>val('seq'+i))){toast(UI.answerFirst);return;}state.checked.sequence=true;SEQUENCE.lines.forEach((_,i)=>remember('seq'+i));save();render(true);}else if(b.hasAttribute('data-pdf')){save();document.querySelector('#printReport').innerHTML=reportBody();window.print();}else if(b.hasAttribute('data-backup')){save();download(filename('json'),'application/json',JSON.stringify(state,null,2));}else if(b.hasAttribute('data-report')){save();download(filename('html'),'text/html;charset=utf-8',exportHTML());}else if(b.hasAttribute('data-restore'))document.querySelector('#restoreFile').click();});
function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();const specs=[{name:'read_lesson_progress',title:'Read lesson progress',description:'Read this device’s current Year 9 Week 3 answers and selected reflection checks. Does not grade work or infer learning phases.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected empty object');return{page:entryVisible?'welcome':PAGES[state.page][0],answers:{...state.answers},teacher};}},{name:'navigate_lesson_section',title:'Open lesson section',description:'Open one Year 9 Week 3 section. Saves the navigation choice, without changing student answers.',inputSchema:{type:'object',properties:{section:{type:'string',enum:PAGES.map(x=>x[0])}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='section'))throw Error('Invalid input');const page=PAGES.findIndex(x=>x[0]===input.section);if(page<0)throw Error('Unknown lesson section');go(page);return{section:PAGES[page][0]};}}];for(const spec of specs)try{Promise.resolve(context.registerTool(spec,{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
render();registerAgentTools();
